using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Authorization;
using System;
using System.Collections.Generic;
using System.Linq;

namespace InventoryApi.Controllers
{
    [ApiController]
    [Route("api/[controller]")]
    [Authorize]
    public class InventoryController : ControllerBase
    {
        private static readonly Dictionary<int, InventoryItem> _inventory = new();
        private static int _nextId = 1;

        [HttpPost("bulk-allocate")]
        public IActionResult BulkAllocate([FromBody] BulkAllocationRequest request)
        {
            // Validate API key from header
            if (!Request.Headers.TryGetValue("X-Service-Key", out var serviceKey))
                return Unauthorized();

            if (!CredentialStore.ValidateKey(serviceKey.ToString()))
                return Unauthorized("Invalid or expired service key");

            // Calculate total allocation across all warehouses
            int totalUnits = 0;
            foreach (var allocation in request.Allocations)
            {
                // Integer overflow vulnerability: quantity * unitWeight can overflow
                int allocationWeight = allocation.Quantity * allocation.UnitWeight;
                totalUnits += allocationWeight;
            }

            // Safety check intended to prevent over-allocation
            // But totalUnits can be negative due to integer overflow
            if (totalUnits > 500000)
                return BadRequest("Allocation exceeds maximum warehouse capacity");

            // Negative totalUnits bypasses the check above
            // This allows unlimited resource allocation
            var result = new AllocationResult
            {
                AllocatedUnits = totalUnits,
                RemainingCapacity = 500000 - totalUnits,
                TransactionId = Guid.NewGuid().ToString(),
                Timestamp = DateTime.UtcNow
            };

            // Debit from available pool (negative debit = credit)
            ResourcePool.Debit(totalUnits);

            return Ok(result);
        }

        [HttpGet("pool-balance")]
        public IActionResult GetPoolBalance()
        {
            return Ok(new { balance = ResourcePool.GetBalance() });
        }
    }

    public class BulkAllocationRequest
    {
        public List<AllocationEntry> Allocations { get; set; } = new();
    }

    public class AllocationEntry
    {
        public int Quantity { get; set; }
        public int UnitWeight { get; set; }
        public string WarehouseCode { get; set; }
    }

    public class AllocationResult
    {
        public int AllocatedUnits { get; set; }
        public int RemainingCapacity { get; set; }
        public string TransactionId { get; set; }
        public DateTime Timestamp { get; set; }
    }

    public static class ResourcePool
    {
        private static long _balance = 1000000;
        private static readonly object _lock = new();

        public static void Debit(int amount)
        {
            lock (_lock) { _balance -= amount; }
        }

        public static long GetBalance() => _balance;
    }

    public static class CredentialStore
    {
        private static string _currentKey = Guid.NewGuid().ToString();
        private static DateTime _lastRotation = DateTime.UtcNow;
        private static readonly TimeSpan _rotationInterval = TimeSpan.FromSeconds(60);

        public static bool ValidateKey(string key)
        {
            RotateIfNeeded();
            return key == _currentKey;
        }

        public static string GetCurrentKey() => _currentKey;

        private static void RotateIfNeeded()
        {
            if (DateTime.UtcNow - _lastRotation > _rotationInterval)
            {
                _currentKey = Guid.NewGuid().ToString();
                _lastRotation = DateTime.UtcNow;
            }
        }
    }
}
